INSERT INTO `buku_digital` (`id_buku`, `judul`, `penulis`, `penerbit`, `tahun_terbit`, `kategori`, `tingkat_kelas`, `deskripsi`, `cover`, `file_buku`, `tipe_sumber`, `dibaca`, `created_at`, `updated_at`) VALUES
('1', 'Buku Siswa Bahasa Indonesia Kelas VII', 'Tim Pengembang Kurikulum', 'Kemdikbudristek', '2024', 'Bahasa Indonesia', 'Kelas 7', 'Buku panduan utama pembelajaran Bahasa Indonesia kelas 7 SMP/MTs Kurikulum Merdeka. Membahas teks deskripsi, teks puisi rakyat, teks cerita fantasi, dan literasi.', 'uploads/buku/covers/cover_indo_7.png', 'uploads/buku/pdf/bahasa_indonesia_7.pdf', 'file', '12', '2026-10-12 14:20:59', '2026-10-12 14:20:59'),
('2', 'Buku Siswa Matematika Kelas VII', 'Tim Pengembang Matematika', 'Kemdikbudristek', '2024', 'Matematika', 'Kelas 7', 'Buku ajar Matematika kelas 7 Kurikulum Merdeka. Membahas materi bilangan bulat, pecahan, aljabar, persamaan linear, dan geometri terapan.', 'uploads/buku/covers/cover_mtk_7.png', 'uploads/buku/pdf/matematika_7.pdf', 'file', '8', '2026-10-12 14:20:59', '2026-10-12 14:20:59'),
('3', 'Ilmu Pengetahuan Alam (IPA) Kelas VII', 'Tim Sains Kurikulum Merdeka', 'Kemdikbudristek & Kemenag', '2024', 'IPA', 'Kelas 7', 'Buku ajar IPA kelas 7 Kurikulum Merdeka yang memadukan konsep fisika, biologi, dan kimia secara kontekstual, observatif, dan menyenangkan.', 'uploads/buku/covers/cover_ipa_7.png', 'uploads/buku/pdf/ipa_7.pdf', 'file', '15', '2026-10-12 14:20:59', '2026-10-12 14:20:59');
